const $=s=>document.querySelector(s),labels=Object.fromEntries(d.models.map(m=>[m.id,m.label]));
const el=(tag,text,cls)=>{const e=document.createElement(tag);if(text!==undefined)e.textContent=text;if(cls)e.className=cls;return e};
$('#intro').textContent=d.evaluation;const method=$('#method');for(const r of Object.values(d.rubric))method.append(el('p',r.label+'（'+r.max+'点）: '+r.description));for(const x of [...d.conditions,...d.limitations])method.append(el('p',x));for(const n of d.outputLicenseNotes||[]){method.append(el('p',n.note));const a=el('a',n.license);a.href=n.url;a.rel='noopener noreferrer';method.append(a)}for(const m of d.models)if(m.loadedGiB)method.append(el('p',m.label+': ロード容量 '+m.loadedGiB+' GiB / VRAM '+m.vramGiB+' GiB'));
let cohort;
function renderCases(){const container=$('#cases');container.replaceChildren();const domain=$('#domain').value,dir=$('#direction').value,engine=$('#engine').value;for(const c of d.cases){if(c.cohort!==cohort.id||domain!=='all'&&c.domain!==domain||dir!=='all'&&c.sourceLanguage!==dir)continue;const article=el('article',undefined,'case');article.append(el('h3',c.id+' · '+({finance:'決算',paper:'論文',daily:'日常'})[c.domain]+' · '+(c.sourceLanguage==='en'?'英日':'日英')),el('p',c.source,'source'));const detail=el('details');detail.append(el('summary','保持すべき命題'));for(const x of c.critical)detail.append(el('p',x));article.append(detail);for(const t of c.translations){if(engine!=='all'&&t.engine!==engine)continue;const div=el('section',undefined,'translation');div.append(el('strong',labels[t.engine]));if(t.meaning2OrLower)div.append(el('span',' 意味の要確認箇所あり','weak'));div.append(el('p',t.output),el('div','意味 '+t.scores.meaning+'/4 · 文脈 '+t.scores.context+'/3 · 自然さ '+t.scores.naturalness+'/3 · 意図 '+t.scores.intent_style+'/2 · 合計 '+t.scores.total+'/12','score'),el('p',t.assessment,'assessment'));article.append(div)}container.append(article)}}
function activate(){const id=location.hash.slice(1);cohort=d.cohorts.find(c=>c.id===id)||d.cohorts[0];for(const b of document.querySelectorAll('[data-cohort]'))b.setAttribute('aria-pressed',String(b.dataset.cohort===cohort.id));$('#cohort-title').textContent=cohort.label;$('#purpose').textContent=cohort.purpose;$('#finding').textContent=cohort.finding;const body=$('#summary');body.replaceChildren();for(const r of cohort.summary){const tr=el('tr'),t=r.elapsedSeconds,values=[r.label,r.meanScore.toFixed(2),r.directionMeans.en.toFixed(2)+' / '+r.directionMeans.ja.toFixed(2),r.meaning2OrLower+' / '+r.evaluated,t?t.first.toFixed(2)+'s / '+t.subsequentMedian.toFixed(2)+'s':'比較対象外'];for(const v of values)tr.append(el('td',v));body.append(tr)}const selected=$('#engine').value;$('#engine').replaceChildren();let o=el('option','すべて');o.value='all';$('#engine').append(o);for(const id of cohort.engineIds){o=el('option',labels[id]);o.value=id;$('#engine').append(o)}$('#engine').value=cohort.engineIds.includes(selected)?selected:'all';renderCases()}
for(const b of document.querySelectorAll('[data-cohort]'))b.addEventListener('click',()=>{location.hash=b.dataset.cohort});for(const id of ['domain','direction','engine'])$('#'+id).addEventListener('change',renderCases);addEventListener('hashchange',activate);activate();
